mapper.select:
SELECT id, space_id, space_name, space_type, description, status, create_time, update_time
FROM ai_knowledge_space
WHERE space_id = #{spaceId}

SELECT id, workspace_id, doc_id, mode, question, answer, rewritten_query, retrieval_scope, final_context,
       retrieved_chunks_json, retrieved_chunk_details_json, status, error_message, create_time
FROM document_task_record


        workspace_id = #{workspaceId}


ORDER BY create_time DESC, id DESC
LIMIT #{limit}
